/**
 * QR rendering adapter for Receive payment requests.
 *
 * The matrix is generated by the well-tested `qrcode` package. Keeping this
 * file as a tiny adapter means the UI can stay SVG-based while the actual
 * symbol remains compatible with standard phone-camera decoders.
 */

import QRCode from 'qrcode'

export function encodeQrCode(text: string): boolean[][] {
  const qr = QRCode.create(text, {
    errorCorrectionLevel: 'M',
  })
  const size = qr.modules.size
  return Array.from({ length: size }, (_, row) =>
    Array.from({ length: size }, (_, column) => qr.modules.data[row * size + column] === 1),
  )
}

/**
 * Generates an SVG string containing the exact QR matrix.
 */
export function generateQrSvgString(text: string, size: number = 130): string {
  const modules = encodeQrCode(text)
  const moduleCount = modules.length
  const margin = 4
  const total = moduleCount + margin * 2
  const scale = size / total

  let rects = ''
  for (let row = 0; row < moduleCount; row += 1) {
    for (let column = 0; column < moduleCount; column += 1) {
      if (!modules[row][column]) continue
      const x = (column + margin) * scale
      const y = (row + margin) * scale
      rects += `<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${scale.toFixed(2)}" height="${scale.toFixed(2)}" fill="#191820" />`
    }
  }

  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="${size}" height="${size}" rx="8" fill="#ffffff" />
    ${rects}
  </svg>`
}
